function NovaPasswordScreen({ onConcluido }) {
  const [password, setPassword] = useState("");
  const [aGuardar, setAGuardar] = useState(false);
  const [erro, setErro] = useState("");

  const guardar = async () => {
    if (password.trim().length < 6) {
      setErro("A palavra-passe precisa de ter pelo menos 6 caracteres.");
      return;
    }
    setErro("");
    setAGuardar(true);
    try {
      const { error } = await supabase.auth.updateUser({ password: password.trim() });
      if (error) throw error;
      onConcluido();
    } catch (e) {
      setErro("Não foi possível guardar. Tenta outra vez.");
    } finally {
      setAGuardar(false);
    }
  };

  return (
    <div
      className="min-h-screen w-full flex flex-col items-center justify-center px-8"
      style={{ backgroundColor: palette.cream }}
    >
      <div className="mb-10">
        <Wordmark />
      </div>
      <div className="w-full max-w-xs space-y-4">
        <p className="font-serif text-xl text-center mb-2" style={{ color: palette.navy }}>Define uma nova palavra-passe</p>
        <label className="block">
          <div
            className="mt-2 flex items-center gap-2 rounded-xl px-4 py-3"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}` }}
          >
            <PenLine size={16} style={{ color: palette.gold }} />
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Nova palavra-passe"
              className="w-full bg-transparent outline-none text-sm"
              style={{ color: palette.ink }}
            />
          </div>
        </label>
        <button
          onClick={guardar}
          disabled={aGuardar}
          className="w-full rounded-full py-3.5 font-medium text-sm tracking-wide disabled:opacity-60"
          style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
        >
          {aGuardar ? "A guardar..." : "Guardar e entrar"}
        </button>
        {erro && <p className="text-center text-xs" style={{ color: "#B23A3A" }}>{erro}</p>}
      </div>
    </div>
  );
}

