/* ---------------------------------------------------------
   Podcast
--------------------------------------------------------- */
function PodcastScreen({ onBack, souDona }) {
  const [escolaId, setEscolaId] = useState(escolas[0].id);
  const [episodios, setEpisodios] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [aAdicionar, setAAdicionar] = useState(false);
  const [novoTitulo, setNovoTitulo] = useState("");
  const [novaDescricao, setNovaDescricao] = useState("");
  const [novaDuracao, setNovaDuracao] = useState("");
  const [novoUrl, setNovoUrl] = useState("");
  const [aGuardar, setAGuardar] = useState(false);

  const spotifyUrl = podcastPorEscola[escolaId]?.spotifyUrl;

  const carregarEpisodios = () => {
    setCarregando(true);
    supabase
      .from("podcast_episodios")
      .select("*")
      .eq("escola_id", escolaId)
      .order("criado_em", { ascending: false })
      .then(({ data }) => {
        setEpisodios(data || []);
        setCarregando(false);
      })
      .catch(() => setCarregando(false));
  };

  useEffect(() => { carregarEpisodios(); }, [escolaId]);

  const adicionarEpisodio = async () => {
    if (!novoTitulo.trim() || !novoUrl.trim()) return;
    setAGuardar(true);
    await supabase.from("podcast_episodios").insert({
      escola_id: escolaId,
      titulo: novoTitulo.trim(),
      descricao: novaDescricao.trim(),
      duracao: novaDuracao.trim(),
      url: novoUrl.trim(),
    });
    setNovoTitulo(""); setNovaDescricao(""); setNovaDuracao(""); setNovoUrl("");
    setAAdicionar(false);
    setAGuardar(false);
    carregarEpisodios();
  };

  const apagarEpisodio = async (id) => {
    await supabase.from("podcast_episodios").delete().eq("id", id);
    carregarEpisodios();
  };

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="EPISÓDIOS" title="Podcast" onBack={onBack} />

      <div className="px-6 mb-5 flex gap-2">
        {escolas.map((e) => {
          const ativo = e.id === escolaId;
          return (
            <button
              key={e.id}
              onClick={() => setEscolaId(e.id)}
              className="flex-1 rounded-full py-2 text-xs font-medium tracking-wide transition"
              style={
                ativo
                  ? { backgroundColor: palette.navy, color: palette.creamSoft }
                  : { backgroundColor: palette.card, color: palette.navySoft, border: `1px solid ${palette.goldSoft}55` }
              }
            >
              {e.nome}
            </button>
          );
        })}
      </div>

      <div className="px-6 mb-5">
        {spotifyUrl ? (
          <a
            href={spotifyUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="w-full rounded-2xl px-5 py-4 flex items-center gap-4 transition active:scale-[0.98]"
            style={{ backgroundColor: palette.navy }}
          >
            <div
              className="w-11 h-11 rounded-full flex items-center justify-center shrink-0"
              style={{ border: `1.5px solid ${palette.gold}` }}
            >
              <Headphones size={18} strokeWidth={1.6} style={{ color: palette.gold }} />
            </div>
            <div className="flex-1">
              <p className="font-serif text-lg leading-tight" style={{ color: palette.creamSoft }}>Ouvir no Spotify</p>
              <p className="text-xs mt-0.5" style={{ color: palette.goldSoft }}>Todos os episódios do programa</p>
            </div>
            <ArrowRight size={18} style={{ color: palette.gold }} />
          </a>
        ) : (
          <div
            className="w-full rounded-2xl px-5 py-4 flex items-center gap-4"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
          >
            <div
              className="w-11 h-11 rounded-full flex items-center justify-center shrink-0"
              style={{ border: `1.5px solid ${palette.goldSoft}` }}
            >
              <Headphones size={18} strokeWidth={1.6} style={{ color: palette.navySoft }} />
            </div>
            <div className="flex-1">
              <p className="font-serif text-lg leading-tight" style={{ color: palette.navy }}>Programa a chegar</p>
              <p className="text-xs mt-0.5" style={{ color: palette.navySoft }}>Ainda sem link do Spotify</p>
            </div>
          </div>
        )}
      </div>

      {souDona && (
        <div className="px-6 mb-5">
          {!aAdicionar ? (
            <button
              onClick={() => setAAdicionar(true)}
              className="w-full rounded-2xl px-5 py-3.5 flex items-center justify-center gap-2 text-sm font-medium"
              style={{ backgroundColor: palette.card, border: `1.5px dashed ${palette.gold}` }}
            >
              <Plus size={16} style={{ color: palette.gold }} />
              <span style={{ color: palette.navy }}>Adicionar episódio novo</span>
            </button>
          ) : (
            <div className="rounded-2xl px-5 py-4 space-y-2.5" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
              <p className="text-[11px] tracking-[0.2em] font-medium mb-1" style={{ color: palette.gold }}>NOVO EPISÓDIO — {escolas.find(e => e.id === escolaId)?.nome}</p>
              <input
                value={novoTitulo}
                onChange={(e) => setNovoTitulo(e.target.value)}
                placeholder="Título do episódio"
                className="w-full rounded-xl px-3.5 py-2.5 text-sm"
                style={{ backgroundColor: palette.creamSoft, color: palette.ink }}
              />
              <input
                value={novaDescricao}
                onChange={(e) => setNovaDescricao(e.target.value)}
                placeholder="Descrição curta (opcional)"
                className="w-full rounded-xl px-3.5 py-2.5 text-sm"
                style={{ backgroundColor: palette.creamSoft, color: palette.ink }}
              />
              <input
                value={novaDuracao}
                onChange={(e) => setNovaDuracao(e.target.value)}
                placeholder="Duração (ex: 15 min)"
                className="w-full rounded-xl px-3.5 py-2.5 text-sm"
                style={{ backgroundColor: palette.creamSoft, color: palette.ink }}
              />
              <input
                value={novoUrl}
                onChange={(e) => setNovoUrl(e.target.value)}
                placeholder="Link do episódio no Spotify"
                className="w-full rounded-xl px-3.5 py-2.5 text-sm"
                style={{ backgroundColor: palette.creamSoft, color: palette.ink }}
              />
              <div className="flex gap-2 pt-1">
                <button
                  onClick={() => setAAdicionar(false)}
                  className="flex-1 rounded-xl py-2.5 text-sm font-medium"
                  style={{ backgroundColor: palette.creamSoft, color: palette.navySoft }}
                >
                  Cancelar
                </button>
                <button
                  onClick={adicionarEpisodio}
                  disabled={aGuardar || !novoTitulo.trim() || !novoUrl.trim()}
                  className="flex-1 rounded-xl py-2.5 text-sm font-medium disabled:opacity-50"
                  style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
                >
                  {aGuardar ? "A guardar..." : "Guardar episódio"}
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      <div className="px-6 space-y-3">
        {carregando ? (
          <p className="text-sm text-center py-6" style={{ color: palette.navySoft }}>A carregar episódios...</p>
        ) : episodios.length === 0 ? (
          <p className="text-sm text-center py-6" style={{ color: palette.navySoft }}>Ainda sem episódios aqui.</p>
        ) : (
          episodios.map((ep) => (
            <div key={ep.id} className="flex items-center gap-4 rounded-2xl px-4 py-4" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
              <div className="flex-1 min-w-0">
                <p className="text-[15px] font-medium" style={{ color: palette.ink }}>{ep.titulo}</p>
                {ep.descricao && <p className="text-xs mt-1 leading-relaxed" style={{ color: palette.navySoft }}>{ep.descricao}</p>}
                {ep.duracao && <p className="text-xs mt-1" style={{ color: palette.navySoft }}>{ep.duracao}</p>}
              </div>
              {souDona && (
                <button onClick={() => apagarEpisodio(ep.id)} className="shrink-0 p-1">
                  <Trash2 size={15} style={{ color: palette.navySoft, opacity: 0.6 }} />
                </button>
              )}
              {ep.url ? (
                <a
                  href={ep.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="w-11 h-11 rounded-full flex items-center justify-center shrink-0"
                  style={{ backgroundColor: palette.navy }}
                >
                  <Play size={16} style={{ color: palette.creamSoft }} />
                </a>
              ) : (
                <span
                  className="w-11 h-11 rounded-full flex items-center justify-center shrink-0"
                  style={{ border: `1.5px solid ${palette.goldSoft}`, opacity: 0.6 }}
                >
                  <Play size={16} style={{ color: palette.navySoft }} />
                </span>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Formação
--------------------------------------------------------- */
function mesDoCurso(cursoId) {
  const m = comunidadeMeses.find((mm) => mm.formacaoId === cursoId);
  return m ? m.mes : null;
}

function FormacaoScreen({ onBack, onOpenCurso, cursosConcluidos, escolaFixa }) {
  const [escolaId, setEscolaId] = useState(escolaFixa || escolas[0].id);
  const cursosDaEscola = cursos.filter((c) => c.escolaId === escolaId);
  const nomeEscola = (escolas.find((e) => e.id === escolaId) || {}).nome || "Formação";

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="CURSOS E PROGRAMAS" title={escolaFixa ? nomeEscola : "Formação"} onBack={onBack} />

      {!escolaFixa && (
        <div className="px-6 mb-5 flex gap-2">
          {escolas.map((e) => {
            const ativo = e.id === escolaId;
            return (
              <button
                key={e.id}
                onClick={() => setEscolaId(e.id)}
                className="flex-1 rounded-full py-2 text-xs font-medium tracking-wide transition"
                style={
                  ativo
                    ? { backgroundColor: escolaCor[e.id], color: palette.creamSoft }
                    : { backgroundColor: palette.card, color: palette.navySoft, border: `1px solid ${palette.goldSoft}55` }
                }
              >
                {e.nome}
              </button>
            );
          })}
        </div>
      )}

      {escolaId === "lideranca" && (
        <div className="px-6 mb-5">
          <button
            onClick={() => onOpenCurso(cursos.find((c) => c.titulo === "Conversas que Mudam Equipas"))}
            className="w-full text-left rounded-2xl px-5 py-5"
            style={{ backgroundColor: palette.navy }}
          >
            <p className="text-[11px] tracking-[0.2em] font-medium mb-2" style={{ color: palette.gold }}>PERGUNTA PARA TI</p>
            <p className="font-serif text-lg leading-snug mb-3" style={{ color: palette.creamSoft }}>
              Medo do conflito. Medo de apontarem as tuas falhas. Medo de seres diminuído/a. E se pudesses falar sem nenhum destes medos?
            </p>
            <p className="text-xs flex items-center gap-1" style={{ color: palette.goldSoft }}>
              Explorar em "Conversas que Mudam Equipas" <ChevronRight size={13} />
            </p>
          </button>
        </div>
      )}

      {escolaId === "lideranca" && (
        <div className="px-6 mb-5">
          <button
            onClick={() => onOpenCurso(cursos.find((c) => c.titulo === "Conversas que Mudam Equipas"))}
            className="w-full text-left rounded-2xl px-5 py-5"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
          >
            <p className="text-[11px] tracking-[0.2em] font-medium mb-2" style={{ color: palette.gold }}>PERGUNTA PARA TI</p>
            <p className="font-serif text-lg leading-snug mb-3" style={{ color: palette.navy }}>
              Quantas vezes ficaste calado/a por medo de dizer mal, de não ser entendido/a, ou de a mensagem soar a mais do que querias?
            </p>
            <p className="text-xs flex items-center gap-1" style={{ color: palette.navySoft }}>
              Explorar em "Conversas que Mudam Equipas" <ChevronRight size={13} />
            </p>
          </button>
        </div>
      )}

      <div className="px-6 space-y-3">
        {cursosDaEscola.map((c) => {
          const Icon = tipoIcon[c.tipo];
          const concluido = Boolean(cursosConcluidos[c.id]);
          const mes = mesDoCurso(c.id);
          return (
            <button
              key={c.id}
              onClick={() => onOpenCurso(c)}
              className="w-full flex flex-col gap-2 rounded-2xl px-5 py-4 text-left transition active:scale-[0.98]"
              style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
            >
              {mes && (
                <p className="text-[10px] tracking-[0.2em] font-medium" style={{ color: escolaCor[c.escolaId] }}>{mes.toUpperCase()}</p>
              )}
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style={{ border: `1.5px solid ${escolaCor[c.escolaId]}` }}>
                  <Icon size={16} strokeWidth={1.6} style={{ color: escolaCor[c.escolaId] }} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-serif text-lg leading-snug" style={{ color: palette.navy }}>{c.titulo}</p>
                  <p className="text-xs mt-0.5" style={{ color: palette.navySoft }}>{tipoLabel[c.tipo]} · {c.duracao}</p>
                </div>
                {concluido ? <CheckCircle2 size={18} style={{ color: palette.gold }} /> : <ChevronRight size={18} style={{ color: palette.navySoft }} />}
              </div>
              <p className="text-sm leading-relaxed pl-[52px]" style={{ color: palette.ink }}>{c.promessa}</p>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function ConteudoDetalhe({ curso, concluido, onToggleConcluido, onBack, materiaisDesbloqueados, onDesbloquearMaterial, acessoTotal, formadorAutorizado }) {
  const [aulaExpandida, setAulaExpandida] = useState(null);
  const Icon = tipoIcon[curso.tipo];
  return (
    <div className="pb-28">
      <div className="px-6 pt-8">
        <button onClick={onBack} className="flex items-center gap-1 text-sm font-medium" style={{ color: palette.navySoft }}>
          <ChevronLeft size={16} />
          Voltar
        </button>
      </div>
      <div className="px-6 pt-6">
        <p className="text-[11px] tracking-[0.25em] font-medium mb-2" style={{ color: palette.gold }}>
          {(escolas.find((e) => e.id === curso.escolaId) || {}).nome?.toUpperCase() || "FORMAÇÃO"}
          {mesDoCurso(curso.id) ? ` · ${mesDoCurso(curso.id).toUpperCase()}` : ""}
        </p>
        <h1 className="font-serif text-2xl leading-tight mb-4" style={{ color: palette.navy }}>{curso.titulo}</h1>
        <div className="rounded-2xl aspect-video flex items-center justify-center mb-4" style={{ backgroundColor: palette.navy }}>
          <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ backgroundColor: palette.creamSoft }}>
            <Icon size={22} style={{ color: palette.navy }} />
          </div>
        </div>
        <p className="text-sm" style={{ color: palette.navySoft }}>{tipoLabel[curso.tipo]} · {curso.duracao}{curso.gratuito ? " · Gratuito" : ""}</p>
        {curso.promessa && (
          <p className="text-[15px] leading-relaxed mt-4" style={{ color: palette.ink }}>{curso.promessa}</p>
        )}
        {curso.pergunta && (
          <p className="font-serif text-lg leading-snug mt-4" style={{ color: palette.navy }}>"{curso.pergunta}"</p>
        )}
        {curso.aulas && curso.aulas.length > 0 && (
          <div className="mt-7">
            <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>AULAS</p>
            <div className="space-y-3">
              {curso.aulas.map((aula, i) => {
                const aberta = aulaExpandida === i;
                return (
                  <div key={i} className="rounded-2xl px-4 py-3.5" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                    <button
                      onClick={() => { if (!aberta) registarVisualizacao(curso, i, aula); setAulaExpandida(aberta ? null : i); }}
                      className="w-full flex items-start gap-3 text-left"
                    >
                      <span
                        className="w-6 h-6 rounded-full flex items-center justify-center shrink-0 text-xs font-medium mt-0.5"
                        style={{ border: `1.5px solid ${escolaCor[curso.escolaId]}`, color: escolaCor[curso.escolaId] }}
                      >
                        {i + 1}
                      </span>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between gap-2">
                          <p className="font-serif text-base leading-snug" style={{ color: palette.navy }}>{aula.titulo}</p>
                          {aula.conteudo && (
                            aberta
                              ? <ChevronDown size={16} style={{ color: palette.navySoft, flexShrink: 0 }} />
                              : <ChevronRight size={16} style={{ color: palette.navySoft, flexShrink: 0 }} />
                          )}
                        </div>
                        <p className="text-xs leading-relaxed mt-1" style={{ color: palette.navySoft }}>{aula.descricao}</p>
                      </div>
                    </button>
                    {aberta && aula.conteudo && (
                      <div className="mt-4 pl-9 pr-1">
                        {aula.videoUrl && (
                          <div className="rounded-2xl overflow-hidden aspect-video mb-4" style={{ backgroundColor: palette.navy }}>
                            <iframe
                              src={aula.videoUrl}
                              title={aula.titulo}
                              className="w-full h-full"
                              frameBorder="0"
                              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                              allowFullScreen
                            />
                          </div>
                        )}
                        {(() => {
                          const primeiraFrase = aula.conteudo.split(/(?<=[.!?])\s/)[0];
                          return (
                            <p className="text-sm leading-relaxed mb-2 italic" style={{ color: palette.navySoft }}>{primeiraFrase} — continua no Livro do Aluno.</p>
                          );
                        })()}
                        {aula.materiaisIds && aula.materiaisIds.length > 0 && (
                          <div className="mt-3">
                            <p className="text-[10px] tracking-[0.2em] font-medium mb-2" style={{ color: palette.gold }}>MATERIAL DESTA AULA</p>
                            <div className="space-y-2">
                              {aula.materiaisIds.map((mid) => {
                                const m = materiais.find((mat) => mat.id === mid);
                                if (!m) return null;
                                return (
                                  <MaterialCard
                                    key={mid}
                                    material={m}
                                    desbloqueado={acessoTotal || Boolean(materiaisDesbloqueados[mid])}
                                    onDesbloquear={() => onDesbloquearMaterial(mid)}
                                    desbloqueadoFisico={acessoTotal || Boolean(materiaisDesbloqueados[mid + "-fisico"])}
                                    onDesbloquearFisico={() => onDesbloquearMaterial(mid + "-fisico")}
                                  />
                                );
                              })}
                            </div>
                          </div>
                        )}
                        {aula.materiaisFormadorIds && aula.materiaisFormadorIds.length > 0 && (acessoTotal || formadorAutorizado) && (
                          <div className="mt-3">
                            <p className="text-[10px] tracking-[0.2em] font-medium mb-2" style={{ color: palette.gold }}>MATERIAL DO FORMADOR — ESTA AULA</p>
                            <div className="space-y-2">
                              {aula.materiaisFormadorIds.map((mid) => {
                                const m = materiais.find((mat) => mat.id === mid);
                                if (!m) return null;
                                return (
                                  <MaterialCard
                                    key={mid}
                                    material={m}
                                    desbloqueado={true}
                                    onDesbloquear={() => {}}
                                  />
                                );
                              })}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
        {curso.materiaisIds && curso.materiaisIds.length > 0 && (
          <div className="mt-7">
            <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>MATERIAIS DESTE CURSO</p>
            <div className="space-y-2">
              {curso.materiaisIds.map((mid) => {
                const m = materiais.find((mat) => mat.id === mid);
                if (!m) return null;
                return (
                  <MaterialCard
                    key={mid}
                    material={m}
                    desbloqueado={acessoTotal || Boolean(materiaisDesbloqueados[mid])}
                    onDesbloquear={() => onDesbloquearMaterial(mid)}
                    desbloqueadoFisico={acessoTotal || Boolean(materiaisDesbloqueados[mid + "-fisico"])}
                    onDesbloquearFisico={() => onDesbloquearMaterial(mid + "-fisico")}
                  />
                );
              })}
            </div>
          </div>
        )}
        {curso.materiaisFormadorIds && curso.materiaisFormadorIds.length > 0 && (acessoTotal || formadorAutorizado) && (
          <div className="mt-7">
            <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>MATERIAIS DO FORMADOR</p>
            <p className="text-xs mb-3" style={{ color: palette.navySoft }}>Visíveis só para ti, como formadora autorizada para este curso.</p>
            <div className="space-y-2">
              {curso.materiaisFormadorIds.map((mid) => {
                const m = materiais.find((mat) => mat.id === mid);
                if (!m) return null;
                return (
                  <MaterialCard
                    key={mid}
                    material={m}
                    desbloqueado={true}
                    onDesbloquear={() => {}}
                  />
                );
              })}
            </div>
          </div>
        )}
        <button
          onClick={onToggleConcluido}
          className="w-full rounded-full py-3.5 font-medium text-sm tracking-wide mt-8 flex items-center justify-center gap-2 transition active:scale-[0.98]"
          style={
            concluido
              ? { backgroundColor: "transparent", color: palette.navy, border: `1px solid ${palette.navy}` }
              : { backgroundColor: palette.navy, color: palette.creamSoft }
          }
        >
          {concluido ? "Marcar como não concluído" : "Marcar como concluído"}
        </button>
      </div>
    </div>
  );
}

