const DP_CATEGORIES = ["Todas", "Autoconhecimento", "Crenças", "Hábitos", "Emoções"];

const DP_CATEGORY_ACCENT = {
  Autoconhecimento: "#2C4770",
  "Crenças": "#A85C32",
  "Hábitos": "#5B7553",
  "Emoções": "#8A6D3B",
};

const DP_COLORS = {
  cream: "#F3ECDD",
  cardBg: "#FFFCF5",
  ink: "#2A2318",
  inkSoft: "#655B48",
  navy: "#1E3049",
  gold: "#C89B5C",
  hairline: "#E3D8C0",
};

const DP_serif = "Georgia, 'Iowan Old Style', 'Times New Roman', serif";
const DP_sans = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";

function DP_Logo3S({ size = 34 }) {
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        border: `1.5px solid ${DP_COLORS.navy}`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: DP_serif,
        fontStyle: "italic",
        fontSize: size * 0.42,
        color: DP_COLORS.navy,
        flexShrink: 0,
      }}
    >
      3S
    </div>
  );
}

function DP_Footer() {
  return (
    <div
      style={{
        textAlign: "center",
        fontSize: 11,
        letterSpacing: "0.18em",
        color: DP_COLORS.inkSoft,
        fontFamily: DP_sans,
        paddingTop: 18,
        paddingBottom: 4,
      }}
    >
      SABER · SENTIR · SER
    </div>
  );
}

function DP_ToolCard({ tool, onOpen }) {
  const accent = DP_CATEGORY_ACCENT[tool.category];
  return (
    <button
      onClick={() => onOpen(tool)}
      style={{
        textAlign: "left",
        background: DP_COLORS.cardBg,
        border: `1px solid ${DP_COLORS.hairline}`,
        borderRadius: 14,
        padding: "16px 16px 14px",
        cursor: "pointer",
        display: "flex",
        flexDirection: "column",
        gap: 6,
        width: "100%",
        fontFamily: DP_sans,
      }}
    >
      <div style={{ fontSize: 10.5, letterSpacing: "0.14em", color: accent, fontWeight: 600 }}>
        {tool.category.toUpperCase()}
      </div>
      <div style={{ fontFamily: DP_serif, fontSize: 18, color: DP_COLORS.ink, lineHeight: 1.25 }}>
        {tool.title}
      </div>
      <div style={{ fontSize: 12.5, color: DP_COLORS.inkSoft, fontStyle: "italic" }}>
        {tool.subtitle}
      </div>
    </button>
  );
}

function DP_LetterRow({ code, label, desc, accent }) {
  return (
    <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
      <div
        style={{
          width: 30,
          height: 30,
          borderRadius: "50%",
          background: accent,
          color: "#fff",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: DP_serif,
          fontSize: 14,
          flexShrink: 0,
        }}
      >
        {code}
      </div>
      <div>
        <div style={{ fontSize: 14, fontWeight: 600, color: DP_COLORS.ink }}>{label}</div>
        {desc && <div style={{ fontSize: 13, color: DP_COLORS.inkSoft, marginTop: 1 }}>{desc}</div>}
      </div>
    </div>
  );
}

function DP_BulletRow({ label, desc, accent }) {
  return (
    <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
      <div style={{ width: 6, height: 6, borderRadius: "50%", background: accent, marginTop: 7, flexShrink: 0 }} />
      <div>
        <div style={{ fontSize: 14, fontWeight: desc ? 600 : 400, color: DP_COLORS.ink }}>{label}</div>
        {desc && <div style={{ fontSize: 13, color: DP_COLORS.inkSoft, marginTop: 1 }}>{desc}</div>}
      </div>
    </div>
  );
}

function DP_ToolDetail({ tool, onBack }) {
  const accent = DP_CATEGORY_ACCENT[tool.category];
  return (
    <div style={{ fontFamily: DP_sans, paddingBottom: 8 }}>
      <button
        onClick={onBack}
        style={{
          border: "none",
          background: "none",
          color: accent,
          fontSize: 13.5,
          fontWeight: 600,
          cursor: "pointer",
          padding: "4px 0 14px",
          display: "flex",
          alignItems: "center",
          gap: 4,
        }}
      >
        ← Ferramentas
      </button>

      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
        <DP_Logo3S size={30} />
        <div style={{ fontSize: 10.5, letterSpacing: "0.14em", color: accent, fontWeight: 600 }}>
          FERRAMENTA · {tool.category.toUpperCase()}
        </div>
      </div>

      <div style={{ fontFamily: DP_serif, fontSize: 26, color: DP_COLORS.ink, marginTop: 6 }}>{tool.title}</div>
      <div style={{ fontSize: 14, fontStyle: "italic", color: DP_COLORS.inkSoft, marginBottom: 20 }}>
        {tool.subtitle}
      </div>

      <div
        style={{
          background: DP_COLORS.cardBg,
          border: `1px solid ${DP_COLORS.hairline}`,
          borderRadius: 14,
          padding: 18,
          display: "flex",
          flexDirection: "column",
          gap: 16,
        }}
      >
        {tool.type === "letters" && tool.items.map((it, i) => <DP_LetterRow key={i} {...it} accent={accent} />)}
        {tool.type === "bullets" && tool.items.map((it, i) => <DP_BulletRow key={i} {...it} accent={accent} />)}

        {tool.type === "reframe" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {tool.reframePairs.map((p, i) => (
              <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 13, flexWrap: "wrap" }}>
                <span style={{ color: DP_COLORS.inkSoft, background: DP_COLORS.cream, borderRadius: 8, padding: "6px 10px", flex: "1 1 130px" }}>
                  {p.from}
                </span>
                <span style={{ color: accent }}>→</span>
                <span style={{ color: DP_COLORS.ink, fontWeight: 600, background: "#fff", border: `1px solid ${accent}33`, borderRadius: 8, padding: "6px 10px", flex: "1 1 130px" }}>
                  {p.to}
                </span>
              </div>
            ))}
          </div>
        )}

        {tool.type === "wheel" && (
          <>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {tool.wheelSkills.map((s, i) => (
                <span key={i} style={{ fontSize: 12, padding: "6px 12px", borderRadius: 999, background: DP_COLORS.cream, color: DP_COLORS.ink, border: `1px solid ${accent}44` }}>
                  {s}
                </span>
              ))}
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {tool.wheelSteps.map((s, i) => <DP_BulletRow key={i} label={s} accent={accent} />)}
            </div>
          </>
        )}

        {tool.example && (
          <div style={{ fontSize: 12.5, color: DP_COLORS.inkSoft, background: DP_COLORS.cream, borderRadius: 10, padding: 12, lineHeight: 1.5 }}>
            <span style={{ fontWeight: 700, color: DP_COLORS.ink }}>Exemplo: </span>
            {tool.example}
          </div>
        )}
      </div>

      <div style={{ textAlign: "center", fontFamily: DP_serif, fontStyle: "italic", fontSize: 14.5, color: accent, marginTop: 20, padding: "0 12px" }}>
        “{tool.quote}”
      </div>

      <DP_Footer />
    </div>
  );
}

function FerramentasDesenvolvimentoPessoalScreen({ onBack }) {
  const [category, setCategory] = useState("Todas");
  const [selected, setSelected] = useState(null);

  const filtered = category === "Todas" ? DP_TOOLS : DP_TOOLS.filter((t) => t.category === category);

  return (
    <div style={{ background: DP_COLORS.cream, minHeight: "100vh", padding: "20px 16px 32px", maxWidth: 480, margin: "0 auto" }}>
      {selected ? (
        <DP_ToolDetail tool={selected} onBack={() => setSelected(null)} />
      ) : (
        <>
          <button
            onClick={onBack}
            style={{
              border: "none",
              background: "none",
              color: DP_COLORS.inkSoft,
              fontSize: 13.5,
              fontWeight: 600,
              cursor: "pointer",
              padding: "4px 0 14px",
              display: "flex",
              alignItems: "center",
              gap: 4,
              fontFamily: DP_sans,
            }}
          >
            ← Voltar
          </button>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
            <DP_Logo3S size={36} />
            <div>
              <div style={{ fontFamily: DP_serif, fontSize: 21, color: DP_COLORS.ink, lineHeight: 1.1 }}>
                Escola do Ser
              </div>
              <div style={{ fontSize: 12.5, color: DP_COLORS.inkSoft, fontStyle: "italic" }}>
                Ferramentas de Desenvolvimento Pessoal
              </div>
            </div>
          </div>

          <div style={{ display: "flex", gap: 8, overflowX: "auto", margin: "18px 0 16px", paddingBottom: 2 }}>
            {DP_CATEGORIES.map((c) => {
              const active = c === category;
              const accent = c === "Todas" ? DP_COLORS.navy : DP_CATEGORY_ACCENT[c];
              return (
                <button
                  key={c}
                  onClick={() => setCategory(c)}
                  style={{
                    flexShrink: 0,
                    fontFamily: DP_sans,
                    fontSize: 12.5,
                    fontWeight: 600,
                    padding: "7px 14px",
                    borderRadius: 999,
                    border: `1px solid ${active ? accent : DP_COLORS.hairline}`,
                    background: active ? accent : "transparent",
                    color: active ? "#fff" : DP_COLORS.inkSoft,
                    cursor: "pointer",
                  }}
                >
                  {c}
                </button>
              );
            })}
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            {filtered.map((t) => (
              <DP_ToolCard key={t.id} tool={t} onOpen={setSelected} />
            ))}
          </div>

          <DP_Footer />
        </>
      )}
    </div>
  );
}

